export enum VersionSynchronizerEvents {
    START = 'START',
    PROCESS = 'PROCESS',
    VALIDATE = 'VALIDATE',
    COMPLETE = 'COMPLETE',
    ERROR = 'ERROR'
}

export interface VersionSynchronizerState {
    name: string;
    data?: any;
}

export class VersionSynchronizerStateMachine {
    private currentState: VersionSynchronizerState;

    constructor() {
        this.currentState = { name: 'initial' };
    }

    transition(event: VersionSynchronizerEvents, data?: any): void {
        switch (this.currentState.name) {
            case 'initial':
                if (event === VersionSynchronizerEvents.START) {
                    this.currentState = { name: 'processing', data };
                }
                break;
            case 'processing':
                if (event === VersionSynchronizerEvents.COMPLETE) {
                    this.currentState = { name: 'completed', data };
                }
                break;
        }
    }

    getState(): VersionSynchronizerState {
        return this.currentState;
    }
}
